package autolib.fx;

import javafx.scene.image.Image;

import java.io.ByteArrayInputStream;
import java.util.Base64;

/** The BatStateU seal, embedded so it works no matter where resources live. */
final class BatStateULogo {

    private static final String[] PARTS = {
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };

    private static Image cached;

    private BatStateULogo() { }

    static Image get() {
        if (cached == null) {
            byte[] bytes = Base64.getDecoder().decode(String.join("", PARTS));
            cached = new Image(new ByteArrayInputStream(bytes));
        }
        return cached;
    }
}
